diff --git a/src/log.ts b/src/log.ts
index 4892c8b..b1a3d5f 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,19 @@
+const queue: string[] = [];
+let flushing = false;
+
+const flush = (): void => {
+  if (queue.length === 0 || flushing) return;
+  flushing = true;
+
+  const messages = queue.splice(0);
+  setImmediate(() => {
+    messages.forEach(msg => process.stdout.write(msg));
+    flushing = false;
+    if (queue.length > 0) flush();
+  });
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  queue.push(`${JSON.stringify({ message })}\n`);
+  flush();
 };
